        "script": "var erpRaw = $vars.queryErpRecords1.output;\nvar crmRaw = $vars.queryCrmRecords1.output;\nvar erpRecords = (erpRaw && erpRaw.value) ? erpRaw.value : (Array.isArray(erpRaw) ? erpRaw : []);\nvar crmRecords = (crmRaw && crmRaw.value) ? crmRaw.value : (Array.isArray(crmRaw) ? crmRaw : []);\nvar invoiceNo = $vars.start.output.invoiceNumber;\nvar acctNo = $vars.start.output.accountNumber;\nvar lineNo = Number($vars.start.output.disputedLineNumber);\nvar unitPrice = Number($vars.start.output.disputedUnitPrice);\nvar quantity = Number($vars.start.output.disputedQuantity);\nvar invoiceRows = erpRecords.filter(function(r) { return r.invoiceNumber === invoiceNo; });\nvar matchingLine = invoiceRows.find(function(r) { return Number(r.lineNumber) === lineNo; });\nvar contractedAmount = matchingLine ? Number(matchingLine.amount || 0) : 0;\nvar matchedInvoiceNumber = invoiceRows.length > 0 ? String(invoiceRows[0].invoiceNumber || '') : '';\nvar crmFiltered = crmRecords.filter(function(r) { return r.accountNumber === acctNo; });\nvar crmRow = crmFiltered.length > 0 ? crmFiltered[0] : (crmRecords.length > 0 ? crmRecords[0] : {});\nvar accountTier = String(crmRow.accountTier || '');\nvar invoiced = unitPrice * quantity;\nvar totalOvercharge = invoiced > contractedAmount ? invoiced - contractedAmount : 0;\nvar discrepancyCount = totalOvercharge > 0 ? 1 : 0;\nreturn { totalOvercharge: totalOvercharge, discrepancyCount: discrepancyCount, matchedInvoiceNumber: matchedInvoiceNumber, accountTier: accountTier };"
